// CUB exclusive prefix sum
__global__ void block_prefix_sum(int* data, int* out, int N) {
    typedef cub::BlockScan<int, 256> BlockScan;
    __shared__ typename BlockScan::TempStorage ts;
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int val = (tid < N) ? data[tid] : 0, pval;
    BlockScan(ts).ExclusiveSum(val, pval);
    if (tid < N) out[tid] = pval;
}

// CUB DeviceRadixSort
void sort_pairs(thrust::device_vector<int>& keys,
                thrust::device_vector<float>& vals) {
    void* tmp = nullptr; size_t sz = 0;
    auto kp = thrust::raw_pointer_cast(keys.data());
    auto vp = thrust::raw_pointer_cast(vals.data());
    cub::DeviceRadixSort::SortPairs(tmp, sz, kp, kp, vp, vp, keys.size());
    cudaMalloc(&tmp, sz);
    cub::DeviceRadixSort::SortPairs(tmp, sz, kp, kp, vp, vp, keys.size());
    cudaFree(tmp);
}

// Thrust transform-reduce with non-trivial functor
struct SqrtExpFunctor {
    __host__ __device__ float operator()(const float& x) const {
        return sqrtf(expf(x * 0.1f));
    }
};
float sum_sqrt_exp(thrust::device_vector<float>& v) {
    return thrust::transform_reduce(thrust::device, v.begin(), v.end(),
        SqrtExpFunctor(), 0.0f, thrust::plus<float>());
}

// Maps NCCL to RCCL (ROCm Communications Collective Library).
// ncclAllReduce -> rcclAllReduce; ncclComm_t -> rcclComm_t
// cudaStream_t stream ordering semantics differ on AMD.
#include <cuda_runtime.h>
#include <nccl.h>

__global__ void scale_buffer(float* buf, int N, float s) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N) { buf[idx] *= s; __threadfence_system(); }
}

struct NcclCtx {
    ncclComm_t comm; cudaStream_t stream;
    cudaEvent_t ev_start, ev_end;
    int rank, world_size;
};

void allreduce_avg(NcclCtx* ctx, float* buf, int N) {
    cudaEventRecord(ctx->ev_start, ctx->stream);
    ncclResult_t rc = ncclAllReduce(buf, buf, N, ncclFloat, ncclSum,
                                    ctx->comm, ctx->stream);
    if (rc != ncclSuccess) return;
    cudaEventRecord(ctx->ev_end, ctx->stream);
    cudaStreamWaitEvent(ctx->stream, ctx->ev_end, 0);
    int g = (N + 255) / 256;
    scale_buffer<<<g, 256, 0, ctx->stream>>>(buf, N, 1.0f / ctx->world_size);
}

void init_ctx(NcclCtx* ctx, int rank, int ws, ncclUniqueId id) {
    ctx->rank = rank; ctx->world_size = ws;
    cudaSetDevice(rank);
    cudaStreamCreate(&ctx->stream);
    cudaEventCreate(&ctx->ev_start); cudaEventCreate(&ctx->ev_end);
    ncclCommInitRank(&ctx->comm, ws, id, rank);
}
void free_ctx(NcclCtx* ctx) {
    ncclCommDestroy(ctx->comm); cudaStreamDestroy(ctx->stream);
    cudaEventDestroy(ctx->ev_start); cudaEventDestroy(ctx->ev_end);
}

// cuSPARSELt: 2-out-of-4 structured sparsity on Ampere+ Sparse Tensor Cores.
// AMD has no 2:4 hardware unit. Maps conceptually to rocSPARSE CSR/BSR formats
// with manual pruning. API surface is completely different.
#include <cuda_runtime.h>
#include <cusparseLt.h>

void run_sparse_gemm(
    cusparseLtHandle_t* handle,
    const __half* A_dense, const __half* B, float* C,
    int M, int N, int K)
{
    cusparseLtMatDescriptor_t matA, matB, matC;
    cusparseLtMatmulDescriptor_t matmul;
    cusparseLtMatmulAlgSelection_t alg_sel;
    cusparseLtMatmulPlan_t plan;

    cusparseLtStructuredDescriptorInit(handle, &matA, M, K, K, 16,
        CUDA_R_16F, CUSPARSE_ORDER_ROW, CUSPARSELT_SPARSITY_50_PERCENT);
    cusparseLtDenseDescriptorInit(handle, &matB, K, N, N, 16, CUDA_R_16F, CUSPARSE_ORDER_ROW);
    cusparseLtDenseDescriptorInit(handle, &matC, M, N, N, 16, CUDA_R_32F, CUSPARSE_ORDER_ROW);

    cusparseLtMatmulDescriptorInit(handle, &matmul,
        CUSPARSE_OPERATION_NON_TRANSPOSE, CUSPARSE_OPERATION_NON_TRANSPOSE,
        &matA, &matB, &matC, &matC, CUSPARSE_COMPUTE_TF32);

    cusparseLtMatmulAlgSelectionInit(handle, &alg_sel, &matmul, CUSPARSELT_MATMUL_ALG_DEFAULT);
    int alg = 0;
    cusparseLtMatmulAlgSetAttribute(handle, &alg_sel,
        CUSPARSELT_MATMUL_ALG_CONFIG_ID, &alg, sizeof(alg));

    size_t ws_size;
    cusparseLtMatmulPlanInit(handle, &plan, &matmul, &alg_sel);
    cusparseLtMatmulGetWorkspace(handle, &plan, &ws_size);
    void* d_ws; cudaMalloc(&d_ws, ws_size);

    void* d_A_compressed;
    size_t comp_size;
    cusparseLtSpMMACompressedSize(handle, &plan, &comp_size);
    cudaMalloc(&d_A_compressed, comp_size);
    cusparseLtSpMMACompress(handle, &plan, A_dense, d_A_compressed, nullptr);

    float alpha = 1.0f, beta = 0.0f;
    cusparseLtMatmul(handle, &plan, &alpha, d_A_compressed, B, &beta, C, C,
        d_ws, nullptr, 0);

    cudaFree(d_ws); cudaFree(d_A_compressed);
    cusparseLtMatmulPlanDestroy(&plan);
}

