#pragma once
#include <cuda_runtime.h>
#include <cuda_fp16.h>

// Half-precision fused multiply-add with saturation
__device__ __forceinline__ __half hfma_sat(__half a, __half b, __half c) {
    return __hfma_sat(a, b, c);
}

// Fast approximate inverse square root (Newton-Raphson, float)
__device__ __forceinline__ float fast_rsqrt(float x) {
    float y = __frsqrt_rn(x);
    // One NR iteration for extra precision
    y = y * (1.5f - 0.5f * x * y * y);
    return y;
}

// Warp-level max reduction using shuffle
__device__ __forceinline__ float warp_reduce_max(float val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1)
        val = fmaxf(val, __shfl_xor_sync(0xFFFFFFFF, val, offset));
    return val;
}

// Warp-level sum reduction using shuffle
__device__ __forceinline__ float warp_reduce_sum(float val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1)
        val += __shfl_xor_sync(0xFFFFFFFF, val, offset);
    return val;
}

// Block-level reduction via shared memory + warp reduction
__device__ float block_reduce_sum(float val, float* smem) {
    int lane = threadIdx.x % 32;
    int warp_id = threadIdx.x / 32;
    val = warp_reduce_sum(val);
    if (lane == 0) smem[warp_id] = val;
    __syncthreads();
    val = (threadIdx.x < (blockDim.x / 32)) ? smem[lane] : 0.0f;
    if (warp_id == 0) val = warp_reduce_sum(val);
    return val;
}

